mapper.select:
SELECT DISTINCT ON (ka.id) ka.id AS assignment_id, ka.parent_assignment_id AS parent_assignment_id, ka.user_id AS user_id, km.id AS master_kpi_id, km.name AS kpi_name, member_u.full_name AS member_name, COALESCE(( SELECT r.code FROM user_roles ur JOIN roles r ON r.id = ur.role_id AND r.deleted_at IS NULL WHERE ur.user_id = member_u.id ORDER BY CASE upper(trim(both FROM r.code)) WHEN 'GM' THEN 1 WHEN 'PM' THEN 2 WHEN 'LEADER' THEN 3 WHEN 'MEMBER' THEN 4 ELSE 5 END, r.code LIMIT 1 ), '') AS role_code, dept_mgr_u.full_name AS pm_name, leader_u.full_name AS leader_name, assign_dept.name AS department_name, ka.status_code, NULL::text AS evidences FROM kpi_assignments ka JOIN kpis_information ki ON ka.kpi_info_id = ki.id AND ki.deleted_at IS NULL JOIN kpi_master km ON ki.master_kpi_id = km.id AND km.deleted_at IS NULL JOIN kpi_cycles kc ON kc.id = ka.cycle_id JOIN users member_u ON ka.user_id = member_u.id AND member_u.deleted_at IS NULL LEFT JOIN user_departments ud ON ud.user_id = ka.user_id AND ud.is_primary = TRUE LEFT JOIN users leader_u ON leader_u.id = ud.supervisor_id AND leader_u.deleted_at IS NULL LEFT JOIN user_departments prim_ud ON prim_ud.user_id = ka.user_id AND prim_ud.is_primary = TRUE INNER JOIN departments assign_dept ON assign_dept.id = COALESCE(ka.department_id, prim_ud.department_id) AND assign_dept.deleted_at IS NULL AND assign_dept.manager_id = #{pmId, jdbcType=OTHER} LEFT JOIN users dept_mgr_u ON dept_mgr_u.id = assign_dept.manager_id AND dept_mgr_u.deleted_at IS NULL WHERE ka.cycle_id = #{cycleId, jdbcType=OTHER} AND ka.deleted_at IS NULL AND ka.user_id IS NOT NULL AND ka.status_code IN
#{s}
AND ( CASE #{phase} WHEN 'mid' THEN NOW() BETWEEN kc.mid_year_start AND kc.mid_year_end WHEN 'yearEnd' THEN NOW() BETWEEN kc.end_year_start AND kc.end_year_end ELSE FALSE END ) ORDER BY ka.id

SELECT EXISTS (
    SELECT 1
    FROM kpi_assignments parent
    JOIN kpis_information ki ON parent.kpi_info_id = ki.id AND ki.deleted_at IS NULL
    JOIN kpi_master km ON ki.master_kpi_id = km.id AND km.deleted_at IS NULL AND km.type_code = 102
    WHERE parent.user_id = #{pmId, jdbcType=OTHER}
      AND parent.cycle_id = #{cycleId, jdbcType=OTHER}
      AND parent.parent_assignment_id IS NULL
      AND parent.deleted_at IS NULL
      AND (
          NOT EXISTS (
              SELECT 1 FROM kpi_assignments ch
              WHERE ch.parent_assignment_id = parent.id AND ch.deleted_at IS NULL
          )
          OR EXISTS (
              SELECT 1 FROM kpi_assignments ch
              WHERE ch.parent_assignment_id = parent.id AND ch.deleted_at IS NULL
                AND ch.user_id IS NOT NULL
                AND ch.user_id <> #{pmId, jdbcType=OTHER}
                AND COALESCE(ch.status_code, 0) < 405
          )
      )
)
